/* From Uiverse.io by nazarbayev01 - Tags: button, active */
.__UIV_SCOPE__ button {
  padding: 1em 2em;
  border: none;
  border-radius: 5px;
  font-weight: bold;
  letter-spacing: 3px;
  background: #DCFFFC;
  text-transform: uppercase;
  color: #088178;
  transition: all 1000ms;
  font-size: 15px;
  position: relative;
  overflow: hidden;
  outline: 2px solid #088178;
}

.__UIV_SCOPE__ button:hover {
  color: #DCFFFC;
  transform: scale(1);
  outline: 2px solid #088178;
  box-shadow: 4px 5px 17px -4px #088178;
}

.__UIV_SCOPE__ button::before {
  content: "";
  position: absolute;
  left: -50px;
  top: 0;
  width: 0;
  height: 100%;
  background-color: #088178;
  transform: skewX(30deg);
  z-index: -1;
  transition: width 1000ms;
}

.__UIV_SCOPE__ button:hover::before {
  width: 250%;
}
